<?php
/**
 * Fetch district counts for VERIFIED cities using EMSIFA v2 API.
 * Reads mapping_summary_v3.json generated by the mapping script.
 * Outputs district_counts.json with per-regency district counts and total.
 */

function fetchJson($url) {
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_TIMEOUT, 30);
    $data = curl_exec($ch);
    if (curl_errno($ch)) {
        fwrite(STDERR, "cURL error: " . curl_error($ch) . "\n");
        exit(1);
    }
    $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    if ($code !== 200) {
        fwrite(STDERR, "HTTP $code fetching $url\n");
        exit(1);
    }
    return json_decode($data, true);
}

$summaryPath = __DIR__ . '/mapping_summary_v3.json';
if (!file_exists($summaryPath)) {
    fwrite(STDERR, "Mapping summary file not found: $summaryPath\n");
    exit(1);
}

$summaryData = json_decode(file_get_contents($summaryPath), true);
if ($summaryData === null) {
    fwrite(STDERR, "Failed to parse mapping_summary_v3.json\n");
    exit(1);
}

$verifiedCodes = [];
foreach ($summaryData['details'] as $city) {
    $classification = $city['classification'] ?? '';
    if (strpos($classification, 'VERIFIED') === 0) {
        // Expected exactly one match for verified entries
        if (!empty($city['matches'])) {
            foreach ($city['matches'] as $match) {
                $code = $match['code'];
                $name = $match['name'];
                $verifiedCodes[$code] = $name; // use code as key to deduplicate
            }
        }
    }
}

$results = [];
$totalDistricts = 0;
foreach ($verifiedCodes as $code => $regencyName) {
    $url = "https://www.emsifa.com/api-wilayah-indonesia/v2/districts/{$code}.json";
    $districtData = fetchJson($url);
    // EMSIFA v2 returns { "data": [ {"id":..., "name":...}, ... ] }
    $districts = $districtData['data'] ?? [];
    $count = count($districts);
    $totalDistricts += $count;
    $results[$code] = [
        'regency_name' => $regencyName,
        'district_count' => $count,
        // Store full district objects (id and name) for accurate EMSIFA IDs
        'districts' => $districts,
    ];
    echo "Fetched {$count} districts for {$regencyName} ({$code})\n";
}

$output = [
    'total_verified_cities' => count($verifiedCodes),
    'total_districts' => $totalDistricts,
    'details' => $results,
];

file_put_contents('district_counts.json', json_encode($output, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));

echo "District counts written to district_counts.json\n";
?>